orderType = string(read("Prosím, zvoľte spôsob objednávky v dvojitých úvodzovkách: \"app\", \"counter\", \"waiter\""));

create object instance order of Order;
if (orderType == "app")
    create object instance order of AppOrder;
    distribution = string(read("Prosím, zvoľte spôsob doručenia v dvojitých úvodzovkách: \"home\", \"counter\", \"table\""));
    if (distribution == "home")
	create object instance order.distributionMethod of HomeDelivery;
    elif (distribution == "counter")
	create object instance order.distributionMethod of CounterPickup;
    else
	create object instance order.distributionMethod of TableService;
    end if;

elif (orderType == "counter")
    create object instance order of CounterOrder; 
    distribution = string(read("Prosím, zvoľte spôsob doručenia v dvojitých úvodzovkách: \"counter\", \"table\""));
    if (distribution == "counter")
	create object instance order.distributionMethod of CounterPickup;
    else
	create object instance order.distributionMethod of TableService;
    end if;

else
    create object instance order of WaiterOrder;
    distribution = string(read("Prosím, zvoľte spôsob doručenia v dvojitých úvodzovkách: \"counter\", \"table\""));
    if (distribution == "counter")
	create object instance order.distributionMethod of CounterPickup;
    else
	create object instance order.distributionMethod of TableService;
    end if;
end if;

order.processOrder();

